from __future__ import annotations
import json, hashlib
from pathlib import Path
from collections import Counter

ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'outputs/sign_coverage_audit/2026-10-04'
def load(n): return json.loads((OUT/n).read_text())
def sha(p):
 h=hashlib.sha256(); h.update(p.read_bytes()); return h.hexdigest()
def rel(p):
 try:return str(p.resolve().relative_to(ROOT))
 except ValueError:return str(p.resolve())
def main():
 v=load('validation_report.json'); s=load('project_inventory_summary.json'); c=load('catalog.json');
 source=load('sources/source_register.json'); rec=load('project_records.json'); unknown=load('project_records_outside_official_phrase_catalog.json')
 active=[r for r in rec if r['active']]
 by_issue=Counter(i for r in active for i in r['issues'])
 status=v['status_counts']; total=v['catalog_items']
 # Include useful representative tables, with complete machine-readable appendices linked below.
 missing_img=[x for x in c['items'] if 'image_missing_or_unreadable' in x['issues'] or x['status']=='MISSING_FROM_PROJECT']
 unv=[x for x in c['items'] if x['status']=='UNVERIFIED']
 dup=v['official_code_duplicate_details']
 lines=[]
 lines += ['# LexiSignVQA - kiểm kê độ bao phủ biển báo','',f'- Ngày kiểm kê: **2026-10-04**.','- Kết luận phạm vi: catalog pháp lý được trích từ **QCVN 41:2024/BGTVT**, gồm mã biển, biến thể, biển phụ và mã chỉ dẫn đường cao tốc được nêu bằng cụm “Biển số” trong bản PDF chính thức. Các hình không có mã được giữ trong `sources/official_figure_register.json`, không tự đặt mã mới.','- Catalog có **444 mục mã/biến thể**. 172 mục chưa có record mã khớp trong LawDB đang dùng; 37 mục cần rà soát thủ công vì bộ trích xuất chưa nối được tới phần định nghĩa. Không có cơ sở để đánh dấu `VERIFIED_COMPLETE`.','', '## Nguồn và phạm vi pháp lý','',f'- Thông tư 51/2024/TT-BGTVT (ban hành 15/11/2024, hiệu lực 01/01/2025; Điều 1 và Điều 2 khoản 1-2): [PDF chính thức](https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/11/51-bgtvt.pdf). Thông tư này ban hành QCVN 41:2024/BGTVT và thay QCVN 41:2019/BGTVT.','- Bản QCVN kèm theo: [51-bgtvt-kem.pdf](https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/11/51-bgtvt-kem.pdf), 403 trang, tải trực tiếp ngày 2026-10-04. Phụ lục B-E là ý nghĩa/sử dụng biển cấm, nguy hiểm, hiệu lệnh, chỉ dẫn; Phụ lục F là biển phụ; Phụ lục P là biển chỉ dẫn cao tốc.','- Trạng thái hiệu lực hiển thị tại [VSQI](https://tieuchuanxaydung.vsqi.gov.vn/quychuan/view?sohieu=QCVN%C2%A041%3A2024%2FBGTVT): “A - Còn hiệu lực”. CSDL quốc gia VBPL trả HTTP 403 trong lần truy cập này, nên lịch sử sửa đổi tại đó được ghi `unverified`.','- LawDB cũng chứa `36/2024/QH15` (89 điều), nhưng luật này không được dùng để tự mở rộng danh mục mã biển; việc xác minh toàn văn hợp nhất của luật được ghi `unverified`.','- Phạm vi QCVN rộng hơn biển báo (đèn, vạch, cọc tiêu, rào chắn, cột Km, thiết bị âm thanh). Các mục ngoài biển báo không bị bỏ qua: chúng được liệt kê trong inventory/figure register và không được gán mã biển giả.','', '## Dữ liệu project và provenance','',f'- LawDB đang dùng: `{s["settings"]["lawdb_json_sign_parsing_path"]}`; bản gốc `{s["settings"]["lawdb_json_path"]}`; ảnh gốc `{s["settings"]["lawdb_image_dir"]}`; crop `{s["settings"]["lawdb_extracted_sign_dir"]}`. `data/law_db` là symlink tới `data/raw/law_db`.','- Bản parse đang dùng có 489 detailed signs thuộc QCVN và 0 thuộc Luật 36/2024/QH15; 460 record không có explicit `sign_code`, 29 record có trạng thái review `pending`; 31 record có tên dạng “Biển báo chưa xác định từ context”.','- Snapshot ảnh: 2.064 tệp được quét; tệp đều decode/open được trong lần kiểm tra này. Decode thành công chỉ chứng minh tệp mở được, không chứng minh ảnh đúng biển.','- Qdrant endpoint `http://localhost:6333` truy cập được. Collection cấu hình `lawdb_processed_by_imageprocessing_and_clip-gmp-vit-l-14` trả HTTP 404. Collection khác `traffic_law_signs` có 1.214 điểm và đã scroll hết, nhưng payload/schema khác (`lawdb-sign-patch-v1`) nên chỉ ghi là collection thay thế quan sát được; không coi là ingest thành công của pipeline cấu hình.','', '## Trạng thái catalog','', '| Trạng thái | Số mục | Tỷ lệ |','|---|---:|---:|']
 for k in ['VERIFIED_COMPLETE','PARTIAL','MISSING_FROM_PROJECT','CONFLICT','UNVERIFIED']:
  lines.append(f'| `{k}` | {status[k]} | {v["status_percentages"][k]:.2f}% |')
 lines += ['', 'Diễn giải: `PARTIAL` có record LawDB nhưng còn thiếu mã tường minh, điều kiện có cấu trúc, Qdrant cấu hình hoặc xác minh ngữ nghĩa ảnh. `MISSING_FROM_PROJECT` có trong nguồn pháp lý nhưng không có record mã khớp. `UNVERIFIED` là mục có nguồn PDF nhưng chưa nối được tự động tới phần định nghĩa. `CONFLICT` và `VERIFIED_COMPLETE` đều bằng 0; đây là kết quả kiểm kê, không phải khẳng định không có lỗi ngữ nghĩa.', '', '## Lỗ hổng theo trường dữ liệu', '', '| Hạng mục | Kết quả |', '|---|---:|', f'| Record active không có effective sign code | {v["active_project_records_without_effective_code"]} |', f'| Crop thiếu | {v["active_project_records_missing_crop"]} |', f'| Crop không mở được | {v["active_project_records_unreadable_crop"]} |', f'| Ảnh gốc suy ra thiếu | {v["active_project_records_missing_original"]} |', f'| Fallback/generic metadata | {v["active_project_records_generic_or_fallback"]} |', f'| Article mapping thiếu trong raw LawDB | {v["article_mappings_missing"]} |', f'| Mã active không có trong phrase catalog pháp lý | {len(v["project_codes_not_in_official_phrase_catalog"])} mã |', '', 'Không có crop không mở được trong lần kiểm tra. Các thiếu/mâu thuẫn về semantic identity của ảnh chưa thể kết luận tự động và được ghi `image_identity_status=unverified` trong `project_records.json`.', '', '## Mã lạ, mã trùng và sai biến thể', '', f'- Mã dự án không thấy trong cụm “Biển số” của QCVN: `{", ".join(v["project_codes_not_in_official_phrase_catalog"])}`. Toàn bộ record tương ứng nằm trong `project_records_outside_official_phrase_catalog.json`; không bị loại khỏi inventory. Một số là mã mục phụ lục/fallback (`D.15`, `F.15`, `CT.*`, `DT.*`, `QL.*`, `S.*`) chứ không phải mã biển chuẩn được xác nhận.',f'- Có **{v["official_code_duplicates_in_source"]}** mã xuất hiện nhiều lần trong PDF (do nhắc lại ở mô tả, hình hoặc bảng); chi tiết đếm trong `validation_report.json`. Đây là lặp nguồn, không tự kết luận record LawDB bị trùng.','- LawDB active có 317 effective codes/407 records; các record cùng mã được giữ riêng. `multiple_active_project_records` được gắn issue thay vì gộp.', '', '## Những mục chưa thể kết luận','', f'- **{len(unv)} mục** cần rà soát thủ công do trích xuất chưa nối được với định nghĩa legal section; mỗi mục vẫn có `legal_basis.verification_status=unverified`.','- Không thể xác nhận “ảnh đúng biển” bằng cách chỉ decode ảnh; cần review hình và đối chiếu caption/figure.','- Không thể xác nhận vector Qdrant của pipeline LexiSignVQA vì collection cấu hình không tồn tại tại thời điểm snapshot. Không suy ra từ JSON hoặc từ collection khác.','- Không xác nhận được đầy đủ lịch sử sửa đổi qua VBPL vì HTTP 403; trạng thái VSQI hiển thị còn hiệu lực được ghi riêng.', '', '## Việc cần xử lý tiếp theo', '', '1. Ưu tiên cao: khôi phục/tái tạo đúng collection cấu hình từ bản parse hiện hành, ghi manifest point count và kiểm tra UID từng mã.','2. Ưu tiên cao: sửa parser để lưu `sign_code` tường minh cho 460 record đang trống; phân biệt mã biển với mã mục phụ lục và fallback metadata.','3. Ưu tiên cao: review thủ công 172 mục missing và 37 mục unverified theo trang PDF/hình; xác nhận biến thể, biển phụ, điều kiện thời gian/phương tiện/hướng/khoảng cách.','4. Ưu tiên vừa: kiểm tra semantic identity của 489 crop so với caption/hình gốc; ghi reviewer evidence thay vì suy từ tên.','5. Ưu tiên vừa: xác minh trạng thái sửa đổi hiện hành tại VBPL khi dịch vụ cho phép và cập nhật `source_register.json`.', '', '## Tệp đầu ra', '', '- `catalog.json`: catalog máy đọc được, 444 canonical IDs duy nhất.','- `catalog.csv`: một dòng/mã-biến thể để rà soát.','- `validation_report.json`: thống kê validator, Qdrant snapshot và test.','- `project_records.json`, `article_inventory.json`, `image_inventory.json`: ledger đối chiếu.','- `sources/official_pages.json`, `sources/official_text.txt`, `sources/official_figure_register.json`: bằng chứng trang PDF.','- `sources/source_register.json`: URL, trạng thái xác minh và giới hạn nguồn.','', '## Validation đã chạy', '', '- `.venv/bin/python -m pytest -q` → **69 passed**.','- Validator catalog: canonical ID không trùng; bài viết, ảnh, crop, mã lạ và collection Qdrant được kiểm tra bằng các script trong `scripts/`.','- Qdrant read-only snapshot: thành công với `traffic_law_signs`; collection cấu hình: HTTP 404, trạng thái `missing`.', '', 'Tất cả số liệu chi tiết và record lạ được giữ trong JSON/CSV để có thể tái chạy và rà soát từng dòng.']
 (OUT/'coverage_report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 # Hash report inputs and outputs without changing source data.
 paths=[OUT/'sources/51-bgtvt-kem.pdf',ROOT/'data/raw/law_db/vlsp2025_law_new.json',ROOT/'data/raw/law_db/vlsp2025_law_new_preprocessed_with_imageprocessing.json',ROOT/'src/settings.py',ROOT/'src/core/lawdb/sign_metadata.py',ROOT/'src/deps/qdrant.py']
 (OUT/'hash_manifest.json').write_text(json.dumps([{'path':rel(p),'sha256':sha(p),'size_bytes':p.stat().st_size} for p in paths],ensure_ascii=False,indent=2),encoding='utf-8')
if __name__=='__main__': main()
